// TH18 v1.00a Stage 2 wave w02.
// Source: st02.ecl.txt MainSub01 1135-1142, GirlC01 574-599, GirlC01_at 601-689.
// Card frame = source frame + 122 (120-frame opening buffer + 2 scheduling frames).
const TIME_LIMIT: int = 912;

// Source etEx 0x200000 (VELTIME): a=60 r=0.5 s=保留角（当前角），then WAIT 120,
// then VELTIME a=60 r=2.5.  Direction stays the birth angle, so set_accel is enough.
// Birth ANIM's animation wait is omitted per policy; its 4*speed retreat is applied at
// fire time in the callers.  d1 = (0.5 - v_birth)/60 (rank-dependent birth speed).
xformdef SHARD_RAMP(d1: fx) {
    @60 set_accel(d1);
    set_accel(0fx);
    wait(120);
    @60 set_accel((2.5fx-0.5fx)/60);
    set_accel(0fx);
}

// --- GirlC01 / GirlC01_at ---------------------------------------------------

// Source 574-599.  setHurtbox(32) -> r16, setHitbox(24) -> r12 (body kept).
async sub girl_c01() {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 3.5fx, EASE_LINEAR);            // source moveVel(pi/2, 3.5)
    move_vel(80, 90deg, 0fx, EASE_QUAD_IN);            // source moveVelTime(80, mode1, pi/2, 0)
    spawn girl_c01_at();
    wait(130);
    move_vel(0, 90deg, 0fx, EASE_LINEAR);              // source moveVel(pi/2, 0)
    move_vel(80, 90deg, 0.2fx, EASE_QUAD_IN);          // source moveVelTime(80, mode1, pi/2, 0.2)
    wait(300);
    move_vel(80, 90deg, 2.2fx, EASE_QUAD_IN);          // source moveVelTime(80, mode1, pi/2, 2.2)
    loop { wait(1000); }
}

// Source slot0: etAim mode10 (alternating-layer ring), fixed-direction half offsets.
// angle = alpha + (-1)^q * (R(i) + H(M,q)), H = floor((q+1)/2)*delta; M is always odd here.
sub fire_shard(n: int, m: int, v: fx, alpha: int, d1: fx) {
    var delta: int = 546;                              // 0.05235988 rad nearest BAM (3 deg)
    for q in 0..m {
        var h: int = ((q+1)/2)*delta;
        for i in 0..n {
            var a: int = (i*65536)/n + h;
            if q % 2 != 0 { a = -a; }
            a = a + alpha;
            var av: angle = a as angle;
            // ANIM a=1 retreat: position -= 4*speed along the birth angle.
            var px: fx = $self_x - 4fx*v*cos(av);
            var py: fx = $self_y - 4fx*v*sin(av);
            _ = fire(TH18_SHARD, 13, px, py, v, av, SHARD_RAMP(d1), none);
        }
    }
}

// Source slot1: etAim mode4 (aimed half-offset ring), alpha=0, delta=3 deg, M=1.
sub fire_oval(n: int, v: fx) {
    var pa: angle = aim_player();                      // one aim sample per source etOn
    var base: int = (pa as int) + 32768/n;
    for i in 0..n {
        var av: angle = (base + (i*65536)/n) as angle;
        var px: fx = $self_x - 4fx*v*cos(av);
        var py: fx = $self_y - 4fx*v*sin(av);
        _ = fire(TH18_OVAL, 1, px, py, v, av, none, none);
    }
}

// Source 601-689.  Rank branch: slot0 N/M/v = 4/3/3.0 (E), 8/3/3.6 (N),
// 8/5/3.6 (H), 8/7/3.6 (L); slot1 N/v = 4/1.6 (E), 8/2.0 (N), 16/2.0 (H/L).
async sub girl_c01_at() {
    wait(63);
    var rank: int = global(GVAR_RANK);
    var n0: int = 8;
    var m0: int = 7;
    var v0: fx = 3.6fx;
    var n1: int = 16;
    var v1: fx = 2.0fx;
    if rank == 0 { n0 = 4; m0 = 3; v0 = 3.0fx; n1 = 4; v1 = 1.6fx; }
    if rank == 1 { m0 = 3; n1 = 8; }
    if rank == 2 { m0 = 5; }
    var d1: fx = (0.5fx-v0)/60;
    var alpha: int = 0;                                // source %A starts at 0 rad
    for j in 0..4 {                                    // source $B=4 loop bodies
        fire_shard(n0, m0, v0, alpha, d1);
        alpha = alpha + 4096;                          // +0.392699 rad = 22.5 deg
        wait(23);
        fire_oval(n1, v1);                             // first etOn(1)
        wait(23);
        fire_oval(n1, v1);                             // second etOn(1)
        wait(22);
    }
}

// --- shell and wave schedule ------------------------------------------------

// MainSub01: one GirlC01, wait 201, then the two side ones.
async sub wave() {
    wait(120);
    _ = spawn_enemy(0fx, -24fx, 3000, 0, 0, 0, girl_c01);
    wait(201);
    _ = spawn_enemy(-120fx, -24fx, 1500, 0, 0, 0, girl_c01);
    _ = spawn_enemy(120fx, -24fx, 1500, 0, 0, 0, girl_c01);
    loop { wait(1000); }
}

// Control enemy at (0,0), no body collision; real girls keep their source boxes.
async sub phase_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, phase_main);
    loop { wait(600); }
}

